-- ===== 017_glossary_terms.sql =====
-- Run once in the Supabase SQL editor BEFORE (or after) uploading the Words screen.
-- Additive only: creates one new table. Nothing existing is changed or removed.
-- Managers' own words for "Words to know". A row with the same word as a built-in
-- term replaces it on the cards; a row marked hidden removes that built-in word.
begin;

create table public.glossary_terms (
  id uuid primary key default gen_random_uuid(),
  restaurant_id uuid not null references public.restaurants(id) on delete cascade,
  term text not null check (char_length(btrim(term)) between 1 and 60),
  say text not null default '' check (char_length(say) <= 120),
  means text not null default '' check (char_length(means) <= 600),
  note text not null default '' check (char_length(note) <= 300),
  also text[] not null default '{}' check (cardinality(also) <= 10),
  hidden boolean not null default false,
  created_by uuid not null default auth.uid() references auth.users(id),
  updated_at timestamptz not null default now(),
  check (hidden or char_length(btrim(means)) > 0)
);
create unique index glossary_terms_one_per_word on public.glossary_terms (restaurant_id, lower(btrim(term)));
alter table public.glossary_terms enable row level security;

create policy "Members read words" on public.glossary_terms for select to authenticated
using (public.can_read_restaurant(restaurant_id));
create policy "Owner adds words" on public.glossary_terms for insert to authenticated
with check (public.is_restaurant_owner(restaurant_id) and created_by = (select auth.uid()));
create policy "Owner edits words" on public.glossary_terms for update to authenticated
using (public.is_restaurant_owner(restaurant_id))
with check (public.is_restaurant_owner(restaurant_id));
create policy "Owner deletes words" on public.glossary_terms for delete to authenticated
using (public.is_restaurant_owner(restaurant_id));

revoke all on public.glossary_terms from public, anon, authenticated;
grant select, insert, update, delete on public.glossary_terms to authenticated;

commit;


-- ===== 018_wine_and_sake.sql =====
-- Wine & Sake: a third part of the library, next to Food and Cocktails.
-- Run once in the Supabase SQL editor. No menu items, quizzes or scores are deleted or changed.
-- Three lines contain DROP. They remove RULES, not data:
--   * the rule listing allowed item types, replaced right after by one that also allows 'wine';
--   * the rule listing allowed categories, replaced right after by one that adds the wine sections;
--   * "drop not null" on photo_path, which makes the photo optional (wine and sake may have none).
-- It also teaches the automatic quiz two wine questions (origin and producer) instead of
-- the food-only sauce questions.
begin;

alter table public.menu_items drop constraint menu_items_content_type_check;
alter table public.menu_items add constraint menu_items_content_type_check check (content_type in ('food','cocktails','wine'));

alter table public.menu_items drop constraint menu_items_category_check;
alter table public.menu_items add constraint menu_items_category_check check (category in ('Ceviches','Tiraditos','Nigiris','Makimonos','Hiyashi Zensai','Yaki Zensai','Mains','Bejitarian','Gentei - Limited','Seika','Pisco Experience','Kero Global','Native','Classic Kero Style','Alcohol-free','Tokubetsu','Other','Makis','Cold starters','Hot starters','Main dishes','Sparkling','White','Rosé','Red','Orange','Dessert','Sake'));

alter table public.menu_items alter column photo_path drop not null;

create or replace function public.build_auto_menu_quiz(mid uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare m public.menu_items; pool text[]; answer text; q jsonb := '[]'; stem text;
begin
 select * into m from public.menu_items where id=mid;
 if not found or not public.can_read_restaurant(m.restaurant_id) then raise exception 'Menu item unavailable'; end if;
 stem := m.name;
 select array_agg(distinct category) into pool from public.menu_items where restaurant_id=m.restaurant_id and content_type=m.content_type;
 q:=q||jsonb_build_array(public.quiz_choice('Which menu category contains '||stem||'?',m.category,pool,'Category'));
 select array_agg(distinct split_part(description,E'\n\n',1)) into pool from public.menu_items where restaurant_id=m.restaurant_id and content_type=m.content_type;
 q:=q||jsonb_build_array(public.quiz_choice('Which recorded description belongs to '||stem||'?',split_part(m.description,E'\n\n',1),pool,'Description'));
 select array_agg(distinct array_to_string(ingredients,', ')) into pool from public.menu_items where restaurant_id=m.restaurant_id and content_type=m.content_type;
 q:=q||jsonb_build_array(public.quiz_choice('Which ingredient list is recorded for '||stem||'?',array_to_string(m.ingredients,', '),pool,'Ingredients'));
 answer:=case when cardinality(m.allergens)=0 then 'Allergen information has not been provided. Ask the manager and kitchen/bar team to verify.' else array_to_string(m.allergens,' · ') end;
 select array_agg(distinct array_to_string(allergens,' · ')) into pool from public.menu_items where restaurant_id=m.restaurant_id;
 pool:=pool||array['Allergen information has not been provided. Ask the manager and kitchen/bar team to verify.'];
 q:=q||jsonb_build_array(public.quiz_choice('What do the recorded allergen notes say for '||stem||'? (CC means cross-contamination.)',answer,pool,'Allergen notes'));
 if m.content_type='cocktails' then
  answer:=coalesce(nullif(trim(substring(m.description from E'Method: ([^\n]+)')),''),'Method not recorded');
  q:=q||jsonb_build_array(public.quiz_choice('Which preparation method is recorded for '||stem||'?',answer,array['Shake','Stir','Building','Method not recorded'],'Preparation method'));
  answer:=coalesce(nullif(trim(substring(m.description from E'Glassware: ([^\n]+)')),''),'Glassware not recorded');
  select array_agg(distinct trim(substring(description from E'Glassware: ([^\n]+)'))) into pool from public.menu_items where restaurant_id=m.restaurant_id and content_type='cocktails';
  q:=q||jsonb_build_array(public.quiz_choice('Which glassware is recorded for '||stem||'?',answer,pool,'Glassware'));
 elsif m.content_type='wine' then
  answer:=coalesce(nullif(trim(m.details->>'region'),''),'Region not recorded');
  select array_agg(distinct trim(details->>'region')) into pool from public.menu_items where restaurant_id=m.restaurant_id and content_type='wine';
  q:=q||jsonb_build_array(public.quiz_choice('Where does '||stem||' come from?',answer,pool,'Origin'));
  answer:=coalesce(nullif(trim(m.details->>'producer'),''),'Producer not recorded');
  select array_agg(distinct trim(details->>'producer')) into pool from public.menu_items where restaurant_id=m.restaurant_id and content_type='wine';
  q:=q||jsonb_build_array(public.quiz_choice('Who makes '||stem||'?',answer,pool,'Producer'));
 else
  answer:=case when position('Sauces and component recipes:' in m.description)>0 then coalesce(nullif(trim(split_part(split_part(split_part(m.description,'Sauces and component recipes:',2),E'\n\nSource:',1),':',1)),''),'No component recipe recorded') else 'No component recipe recorded' end;
  select array_agg(distinct trim(split_part(split_part(split_part(description,'Sauces and component recipes:',2),E'\n\nSource:',1),':',1))) into pool from public.menu_items where restaurant_id=m.restaurant_id and content_type='food' and position('Sauces and component recipes:' in description)>0;
  q:=q||jsonb_build_array(public.quiz_choice('Which sauce or component heads the recorded recipe notes for '||stem||'?',answer,pool,'Sauces and components'));
  select array_agg(distinct name) into pool from public.menu_items where restaurant_id=m.restaurant_id and content_type='food' and (id=m.id or split_part(description,E'\n\n',1)<>split_part(m.description,E'\n\n',1));
  q:=q||jsonb_build_array(public.quiz_choice('Which dish has this recorded description? '||split_part(m.description,E'\n\n',1),m.name,pool,'Dish recognition'));
 end if;
 return jsonb_build_object('version',md5(m.updated_at::text||q::text),'updated_at',m.updated_at::text,'questions',q);
end;
$$;

commit;


-- ===== 019_cocktail_quiz_fields.sql =====
-- Cocktail quizzes read Method and Glassware from their own fields.
-- Run once in the Supabase SQL editor. Nothing is deleted: this only updates the
-- automatic quiz builder. It uses the Method / Glassware fields first and falls back
-- to the old description text, so no cocktail loses its questions.
-- Nothing is removed from the database.
begin;

create or replace function public.build_auto_menu_quiz(mid uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare m public.menu_items; pool text[]; answer text; q jsonb := '[]'; stem text;
begin
 select * into m from public.menu_items where id=mid;
 if not found or not public.can_read_restaurant(m.restaurant_id) then raise exception 'Menu item unavailable'; end if;
 stem := m.name;
 select array_agg(distinct category) into pool from public.menu_items where restaurant_id=m.restaurant_id and content_type=m.content_type;
 q:=q||jsonb_build_array(public.quiz_choice('Which menu category contains '||stem||'?',m.category,pool,'Category'));
 select array_agg(distinct split_part(description,E'\n\n',1)) into pool from public.menu_items where restaurant_id=m.restaurant_id and content_type=m.content_type;
 q:=q||jsonb_build_array(public.quiz_choice('Which recorded description belongs to '||stem||'?',split_part(m.description,E'\n\n',1),pool,'Description'));
 select array_agg(distinct array_to_string(ingredients,', ')) into pool from public.menu_items where restaurant_id=m.restaurant_id and content_type=m.content_type;
 q:=q||jsonb_build_array(public.quiz_choice('Which ingredient list is recorded for '||stem||'?',array_to_string(m.ingredients,', '),pool,'Ingredients'));
 answer:=case when cardinality(m.allergens)=0 then 'Allergen information has not been provided. Ask the manager and kitchen/bar team to verify.' else array_to_string(m.allergens,' · ') end;
 select array_agg(distinct array_to_string(allergens,' · ')) into pool from public.menu_items where restaurant_id=m.restaurant_id;
 pool:=pool||array['Allergen information has not been provided. Ask the manager and kitchen/bar team to verify.'];
 q:=q||jsonb_build_array(public.quiz_choice('What do the recorded allergen notes say for '||stem||'? (CC means cross-contamination.)',answer,pool,'Allergen notes'));
 if m.content_type='cocktails' then
  answer:=coalesce(nullif(trim(m.details->>'method'),''),nullif(trim(substring(m.description from E'Method: ([^\n]+)')),''),'Method not recorded');
  q:=q||jsonb_build_array(public.quiz_choice('Which preparation method is recorded for '||stem||'?',answer,array['Shake','Stir','Building','Method not recorded'],'Preparation method'));
  answer:=coalesce(nullif(trim(m.details->>'glassware'),''),nullif(trim(substring(m.description from E'Glassware: ([^\n]+)')),''),'Glassware not recorded');
  select array_agg(distinct coalesce(nullif(trim(details->>'glassware'),''),trim(substring(description from E'Glassware: ([^\n]+)')))) into pool from public.menu_items where restaurant_id=m.restaurant_id and content_type='cocktails';
  q:=q||jsonb_build_array(public.quiz_choice('Which glassware is recorded for '||stem||'?',answer,pool,'Glassware'));
 elsif m.content_type='wine' then
  answer:=coalesce(nullif(trim(m.details->>'region'),''),'Region not recorded');
  select array_agg(distinct trim(details->>'region')) into pool from public.menu_items where restaurant_id=m.restaurant_id and content_type='wine';
  q:=q||jsonb_build_array(public.quiz_choice('Where does '||stem||' come from?',answer,pool,'Origin'));
  answer:=coalesce(nullif(trim(m.details->>'producer'),''),'Producer not recorded');
  select array_agg(distinct trim(details->>'producer')) into pool from public.menu_items where restaurant_id=m.restaurant_id and content_type='wine';
  q:=q||jsonb_build_array(public.quiz_choice('Who makes '||stem||'?',answer,pool,'Producer'));
 else
  answer:=case when position('Sauces and component recipes:' in m.description)>0 then coalesce(nullif(trim(split_part(split_part(split_part(m.description,'Sauces and component recipes:',2),E'\n\nSource:',1),':',1)),''),'No component recipe recorded') else 'No component recipe recorded' end;
  select array_agg(distinct trim(split_part(split_part(split_part(description,'Sauces and component recipes:',2),E'\n\nSource:',1),':',1))) into pool from public.menu_items where restaurant_id=m.restaurant_id and content_type='food' and position('Sauces and component recipes:' in description)>0;
  q:=q||jsonb_build_array(public.quiz_choice('Which sauce or component heads the recorded recipe notes for '||stem||'?',answer,pool,'Sauces and components'));
  select array_agg(distinct name) into pool from public.menu_items where restaurant_id=m.restaurant_id and content_type='food' and (id=m.id or split_part(description,E'\n\n',1)<>split_part(m.description,E'\n\n',1));
  q:=q||jsonb_build_array(public.quiz_choice('Which dish has this recorded description? '||split_part(m.description,E'\n\n',1),m.name,pool,'Dish recognition'));
 end if;
 return jsonb_build_object('version',md5(m.updated_at::text||q::text),'updated_at',m.updated_at::text,'questions',q);
end;
$$;

commit;


-- ===== 020_preshift_focus_items.sql =====
-- Run once in the Supabase SQL editor BEFORE the app files that post more than one focus item.
-- Additive only: nothing is dropped or removed. The old single-focus column and the old
-- posting function both stay exactly as they are, so the app can be rolled back at any time.
begin;

create table public.shift_focus_items (
  shift_note_id uuid not null references public.shift_notes(id) on delete cascade,
  menu_item_id uuid not null references public.menu_items(id) on delete cascade,
  sort_order smallint not null check (sort_order between 1 and 10),
  primary key (shift_note_id, menu_item_id)
);
create index on public.shift_focus_items(menu_item_id);
alter table public.shift_focus_items enable row level security;

create policy "Members read shift focus" on public.shift_focus_items for select to authenticated
using (exists (select 1 from public.shift_notes n where n.id = shift_note_id and public.can_read_restaurant(n.restaurant_id)));
create policy "Owner adds shift focus" on public.shift_focus_items for insert to authenticated
with check (exists (select 1 from public.shift_notes n where n.id = shift_note_id and public.is_restaurant_owner(n.restaurant_id)));
create policy "Owner edits shift focus" on public.shift_focus_items for update to authenticated
using (exists (select 1 from public.shift_notes n where n.id = shift_note_id and public.is_restaurant_owner(n.restaurant_id)))
with check (exists (select 1 from public.shift_notes n where n.id = shift_note_id and public.is_restaurant_owner(n.restaurant_id)));
create policy "Owner deletes shift focus" on public.shift_focus_items for delete to authenticated
using (exists (select 1 from public.shift_notes n where n.id = shift_note_id and public.is_restaurant_owner(n.restaurant_id)));

revoke all on public.shift_focus_items from public, anon, authenticated;
grant select, insert, update, delete on public.shift_focus_items to authenticated;

-- Same guard the 86 board rows already have: a focus item must belong to this restaurant.
create function public.check_shift_focus_item() returns trigger
language plpgsql set search_path = '' as $$
begin
  if not exists (
    select 1 from public.shift_notes n join public.menu_items m on m.restaurant_id = n.restaurant_id
    where n.id = new.shift_note_id and m.id = new.menu_item_id
  ) then
    raise exception 'A focus item must belong to the board restaurant.' using errcode = '23514';
  end if;
  return new;
end;
$$;
create trigger check_shift_focus_item before insert or update on public.shift_focus_items
for each row execute function public.check_shift_focus_item();
revoke all on function public.check_shift_focus_item() from public, anon, authenticated;

-- Carry every focus item already posted into the new list, so no board loses its dish.
insert into public.shift_focus_items(shift_note_id, menu_item_id, sort_order)
select n.id, n.focus_item_id, 1 from public.shift_notes n where n.focus_item_id is not null
on conflict do nothing;

-- The read snapshot now carries the whole list. Same name and arguments, so this updates
-- the existing function in place rather than removing anything.
create or replace function public.get_preshift_board(rid uuid) returns jsonb
language sql stable security invoker set search_path = '' as $$
  select jsonb_build_object(
    'service_date', current_date,
    'board', (select to_jsonb(n) || jsonb_build_object(
      'focus_item_ids', (
        select coalesce(jsonb_agg(f.menu_item_id order by f.sort_order, f.menu_item_id), '[]'::jsonb)
        from public.shift_focus_items f where f.shift_note_id = n.id
      ),
      'entries', (
        select coalesce(jsonb_agg(to_jsonb(e) order by e.created_at, e.id), '[]'::jsonb)
        from public.shift_board_entries e where e.shift_note_id = n.id
      )
    ) from public.shift_notes n where n.restaurant_id = rid and n.service_date = current_date)
  );
$$;

-- Posting a board with a list of focus items. New name, so the old posting function is
-- untouched and still works if the app is rolled back.
-- One transaction: a failed row rolls back the note, the focus list and the 86 board together.
-- This is NOT a security-definer function; every write is subject to RLS.
create function public.save_preshift_board(
  rid uuid, board_date date, board_note text, focus_ids uuid[], board_entries jsonb
) returns uuid
language plpgsql security invoker set search_path = '' as $$
declare board_id uuid;
begin
  if not public.is_restaurant_owner(rid) then
    raise exception 'Only the restaurant manager can post a pre-shift board.' using errcode = '42501';
  end if;
  if board_date is distinct from current_date then
    raise exception 'The service day has changed. Reload today''s board before posting.';
  end if;
  if board_entries is null or jsonb_typeof(board_entries) <> 'array' then
    raise exception 'Board entries must be a list.' using errcode = '23514';
  end if;
  if coalesce(array_length(focus_ids, 1), 0) > 10 then
    raise exception 'A board can hold up to 10 focus items.' using errcode = '23514';
  end if;

  -- The first focus item also fills the old single-focus column, so anything still
  -- reading that column keeps showing a sensible answer.
  insert into public.shift_notes(restaurant_id, service_date, note, focus_item_id, posted_by)
  values(rid, current_date, board_note, focus_ids[1], auth.uid())
  on conflict (restaurant_id, service_date) do update
  set note = excluded.note, focus_item_id = excluded.focus_item_id, posted_by = excluded.posted_by
  returning id into board_id;

  delete from public.shift_focus_items where shift_note_id = board_id;
  insert into public.shift_focus_items(shift_note_id, menu_item_id, sort_order)
  select board_id, f.id, min(f.ord)::smallint
  from unnest(focus_ids) with ordinality as f(id, ord)
  where f.id is not null
  group by f.id;

  delete from public.shift_board_entries where shift_note_id = board_id;
  insert into public.shift_board_entries(shift_note_id, menu_item_id, status, detail)
  select board_id, e.menu_item_id, e.status, coalesce(e.detail, '')
  from jsonb_to_recordset(board_entries) as e(menu_item_id uuid, status text, detail text);
  return board_id;
end;
$$;
revoke all on function public.save_preshift_board(uuid,date,text,uuid[],jsonb) from public, anon;
grant execute on function public.save_preshift_board(uuid,date,text,uuid[],jsonb) to authenticated;
commit;


-- ===== 021_glossary_owns_its_words.sql =====
