-- ===== 022_access_codes.sql =====
-- Run once in the Supabase SQL editor BEFORE the app files that ask for an access code.
-- Creating a restaurant becomes invite-only: one code, one restaurant, used once.
--
-- Two statements here change something that already exists, and both are explained:
--   * "drop policy \"Users create their own restaurant\"" removes the rule that let any signed-in
--     person insert a restaurant row directly. That rule is exactly the open door we are closing.
--     Nothing is deleted by it: no restaurant, no menu item, no member. Policies are permissions.
--   * "revoke insert on public.restaurants" takes the matching permission away for the same reason.
-- From then on a restaurant can only be created through create_restaurant_with_code below,
-- which checks the code first. Everything else about your data is untouched.
begin;

create table public.access_codes (
  code text primary key check (char_length(btrim(code)) between 4 and 40),
  label text not null default '' check (char_length(label) <= 120),
  created_by uuid not null references auth.users(id),
  created_at timestamptz not null default now(),
  expires_at timestamptz,
  used_at timestamptz,
  used_by uuid references auth.users(id),
  restaurant_id uuid references public.restaurants(id) on delete set null
);
create unique index access_codes_one_per_word on public.access_codes (lower(btrim(code)));
alter table public.access_codes enable row level security;
-- No one reads or writes this table from the app. Only the function below touches it,
-- and only you touch it from the SQL editor. That is why there are no policies.
revoke all on public.access_codes from public, anon, authenticated;

-- Closing the open door. See the note at the top.
drop policy "Users create their own restaurant" on public.restaurants;
revoke insert on public.restaurants from authenticated;

-- The only way to create a restaurant. Security definer, so it can write the row itself
-- after the code checks out; the code and the restaurant are created in one transaction,
-- so a failure leaves neither behind.
create function public.create_restaurant_with_code(access_code text, restaurant_name text)
returns uuid
language plpgsql security definer set search_path = '' as $$
declare wanted text := lower(btrim(coalesce(access_code, '')));
declare found public.access_codes%rowtype;
declare new_id uuid;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in first.' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(restaurant_name, ''))) = 0 then
    raise exception 'Give the restaurant a name.' using errcode = '23514';
  end if;

  select * into found from public.access_codes a
  where lower(btrim(a.code)) = wanted for update;

  if not found.code is not null then
    raise exception 'That access code is not valid. Check it with the person who invited you.' using errcode = '42501';
  end if;
  if found.used_at is not null then
    raise exception 'That access code has already been used.' using errcode = '42501';
  end if;
  if found.expires_at is not null and found.expires_at < now() then
    raise exception 'That access code has expired. Ask for a new one.' using errcode = '42501';
  end if;

  insert into public.restaurants(owner_id, name)
  values ((select auth.uid()), btrim(restaurant_name))
  returning id into new_id;

  update public.access_codes
  set used_at = now(), used_by = (select auth.uid()), restaurant_id = new_id
  where public.access_codes.code = found.code;

  return new_id;
end $$;
revoke all on function public.create_restaurant_with_code(text,text) from public, anon;
grant execute on function public.create_restaurant_with_code(text,text) to authenticated;
commit;


-- ===== 023_sections_and_categories.sql =====
-- Run once in the Supabase SQL editor. Step 1 of taking the menu sections out of the app's code.
--
-- After this, every restaurant owns its own section names and category names, seeded with exactly
-- what it has today, in the same order. Nothing on screen changes until the app files are updated,
-- and nothing here touches a dish, a photo, a quiz, a score, a word or a team member.
--
-- One statement changes something that exists, and it is the point of the whole migration:
--   * "drop constraint menu_items_category_check" removes the rule that only allowed Osaka's
--     category names. That rule is why no other restaurant can file a dish. It is replaced two
--     lines later with a rule that accepts any sensible name. No data is deleted by either line.
begin;

-- The three libraries. Fixed set of three, but every word a restaurant shows is its own.
create table public.menu_sections (
  restaurant_id uuid not null references public.restaurants(id) on delete cascade,
  content_type text not null check (content_type in ('food','cocktails','wine')),
  name text not null check (char_length(btrim(name)) between 1 and 40),
  heading text not null default '' check (char_length(heading) <= 60),
  about text not null default '' check (char_length(about) <= 600),
  item_one text not null default 'item' check (char_length(btrim(item_one)) between 1 and 30),
  item_many text not null default 'items' check (char_length(btrim(item_many)) between 1 and 30),
  updated_at timestamptz not null default now(),
  primary key (restaurant_id, content_type)
);

-- The sections inside a library: Ceviches, Tiraditos, Happy Hour, whatever the restaurant uses.
create table public.menu_categories (
  id uuid primary key default gen_random_uuid(),
  restaurant_id uuid not null references public.restaurants(id) on delete cascade,
  content_type text not null check (content_type in ('food','cocktails','wine')),
  name text not null check (char_length(btrim(name)) between 1 and 40),
  sort_order integer not null default 0,
  archived boolean not null default false,
  created_at timestamptz not null default now()
);
create unique index menu_categories_one_per_name
  on public.menu_categories (restaurant_id, content_type, lower(btrim(name)));
create index menu_categories_by_restaurant on public.menu_categories (restaurant_id, content_type, sort_order);

alter table public.menu_sections enable row level security;
alter table public.menu_categories enable row level security;

create policy "Members read sections" on public.menu_sections for select to authenticated
using (public.can_read_restaurant(restaurant_id));
create policy "Owner writes sections" on public.menu_sections for all to authenticated
using (public.is_restaurant_owner(restaurant_id)) with check (public.is_restaurant_owner(restaurant_id));

create policy "Members read categories" on public.menu_categories for select to authenticated
using (public.can_read_restaurant(restaurant_id));
create policy "Owner writes categories" on public.menu_categories for all to authenticated
using (public.is_restaurant_owner(restaurant_id)) with check (public.is_restaurant_owner(restaurant_id));

revoke all on public.menu_sections, public.menu_categories from public, anon, authenticated;
grant select, insert, update, delete on public.menu_sections, public.menu_categories to authenticated;

-- Seed every existing restaurant with the words the app shows it today.
insert into public.menu_sections(restaurant_id, content_type, name, heading, about, item_one, item_many)
select r.id, s.content_type, s.name, s.heading, s.about, s.item_one, s.item_many
from public.restaurants r
cross join (values
  ('food','Food','Kitchen · Food','','dish','dishes'),
  ('cocktails','Cocktails','Kero Bar · Cocktails','The Nikkei world in a liquid form: inspiration from the culture and rituals of Japan and Peru, combined with their diversity of ingredients, to create a cocktail program that activates the senses.','cocktail','cocktails'),
  ('wine','Wine & Sake','Wine & Sake','','wine','wines and sakes')
) as s(content_type, name, heading, about, item_one, item_many)
on conflict do nothing;

insert into public.menu_categories(restaurant_id, content_type, name, sort_order)
select r.id, c.content_type, c.name, c.sort_order
from public.restaurants r
cross join (values
  ('food','Ceviches',1),('food','Tiraditos',2),('food','Nigiris',3),('food','Makimonos',4),
  ('food','Hiyashi Zensai',5),('food','Yaki Zensai',6),('food','Mains',7),('food','Bejitarian',8),
  ('food','Gentei - Limited',9),('food','Seika',10),('food','Other',11),
  ('cocktails','Pisco Experience',1),('cocktails','Kero Global',2),('cocktails','Native',3),
  ('cocktails','Classic Kero Style',4),('cocktails','Alcohol-free',5),('cocktails','Tokubetsu',6),
  ('cocktails','Other',7),
  ('wine','Sparkling',1),('wine','White',2),('wine','Rosé',3),('wine','Red',4),('wine','Orange',5),
  ('wine','Dessert',6),('wine','Sake',7),('wine','Other',8)
) as c(content_type, name, sort_order)
on conflict do nothing;

-- Any category a restaurant is already using that the seed above did not cover keeps working:
-- it is added at the end of its library rather than being lost.
insert into public.menu_categories(restaurant_id, content_type, name, sort_order)
select distinct m.restaurant_id, m.content_type, btrim(m.category), 900
from public.menu_items m
where btrim(coalesce(m.category,'')) <> ''
on conflict do nothing;

-- The rule that only allowed Osaka's names, replaced by one that accepts any sensible name.
alter table public.menu_items drop constraint menu_items_category_check;
alter table public.menu_items add constraint menu_items_category_check
  check (char_length(btrim(category)) between 1 and 40);

commit;


-- ===== 024_guides.sql =====
-- Run once in the Supabase SQL editor BEFORE the app files that add the Guides switch.
-- Additive only: two new columns on a table you already have. Nothing is renamed,
-- nothing is removed, and every word you have today keeps working exactly as it does.
--
-- What the two columns are for:
--   story       the long write-up — where it comes from, how it compares to what sits
--               next to it on the menu. A word with a story is what HEAT calls a guide.
--   photo_path  where the photo lives in Supabase Storage, in the same private
--               menu-photos bucket and under the same restaurant-id folder the menu
--               photos already use, so no new bucket and no new storage policy.
--
-- Both default to an empty string, so existing words simply have no story and no photo.
-- They stay in Words. None of them becomes a guide until somebody writes one.

begin;

alter table public.glossary_terms
  add column if not exists story text not null default '',
  add column if not exists photo_path text not null default '';

alter table public.glossary_terms
  add constraint glossary_terms_story_length check (char_length(story) <= 4000);

alter table public.glossary_terms
  add constraint glossary_terms_photo_path_length check (char_length(photo_path) <= 300);

commit;


-- ===== 025_standards.sql =====
-- Run once in the Supabase SQL editor BEFORE the app files that add the Standards tab.
-- Additive only: one new table. Nothing existing is touched.
--
-- “Standards” is what the team sees; “sops” is what the database calls it. Renaming the tab
-- later is then a change of one label rather than a migration.
--
-- The steps are an array on the row rather than a table of their own. A procedure is read and
-- written whole, never a step at a time, so a second table would buy nothing and cost a join —
-- and the steps renumber themselves for free.
--
-- Postgres can check how many steps there are but not how long each one is (a CHECK cannot
-- contain a subquery), so the 500-character limit on a single step lives in the form instead.
--
-- The policies are copied from glossary_terms: anyone who can read the restaurant can read the
-- standards, and only the owner can write them. That is what makes servers read-only.

begin;

create table public.sops (
  id uuid primary key default gen_random_uuid(),
  restaurant_id uuid not null references public.restaurants(id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 120),
  section text not null default '' check (char_length(section) <= 60),
  why text not null default '' check (char_length(why) <= 300),
  steps text[] not null default '{}' check (cardinality(steps) <= 40),
  photo_path text not null default '' check (char_length(photo_path) <= 300),
  sort_order integer not null default 0,
  updated_at timestamptz not null default now(),
  created_by uuid not null default auth.uid() references auth.users(id)
);

create unique index sops_one_per_name on public.sops (restaurant_id, lower(btrim(name)));
alter table public.sops enable row level security;

create policy "Members read standards" on public.sops for select to authenticated
using (public.can_read_restaurant(restaurant_id));
create policy "Owner adds standards" on public.sops for insert to authenticated
with check (public.is_restaurant_owner(restaurant_id) and created_by = (select auth.uid()));
create policy "Owner edits standards" on public.sops for update to authenticated
using (public.is_restaurant_owner(restaurant_id))
with check (public.is_restaurant_owner(restaurant_id));
create policy "Owner deletes standards" on public.sops for delete to authenticated
using (public.is_restaurant_owner(restaurant_id));

revoke all on public.sops from public, anon, authenticated;
grant select, insert, update, delete on public.sops to authenticated;

commit;


-- ===== 026_consistent_learning_progress.sql =====
-- Deploy before the matching UI. Additive reporting endpoints; no attempts,
-- assignments, retake limits or existing authorization functions are changed.
begin;

-- One definition of latest completed result and changed-question status.
create or replace function public.learning_results(rid uuid, learner_id uuid)
returns table(menu_item_id uuid, item_name text, correct integer, total integer,
 created_at timestamptz, needs_review boolean)
language sql stable security definer set search_path='' as $$
 select distinct on (a.menu_item_id) a.menu_item_id,m.name,a.correct,a.total,a.created_at,
   a.questions is distinct from public.build_menu_quiz(m.id)->'questions'
 from public.quiz_attempts a join public.menu_items m on m.id=a.menu_item_id
 where a.user_id=learner_id and m.restaurant_id=rid and a.total>0
 order by a.menu_item_id,a.created_at desc,a.id desc;
$$;
-- This helper is private: callers must pass through the authorization below.
revoke all on function public.learning_results(uuid,uuid) from public,anon,authenticated;

create or replace function public.get_quiz_progress(rid uuid)
returns table(menu_item_id uuid,correct integer,total integer,created_at timestamptz,needs_review boolean)
language sql stable security definer set search_path='' as $$
 select r.menu_item_id,r.correct,r.total,r.created_at,r.needs_review
 from public.learning_results(rid,auth.uid()) r
 where public.can_read_restaurant(rid);
$$;

create or replace function public.team_member_progress(rid uuid, learner_id uuid)
returns table(menu_item_id uuid,item_name text,correct integer,total integer,created_at timestamptz,needs_review boolean)
language plpgsql stable security definer set search_path='' as $$
begin
 -- Reuse the deployed Team authorization and membership checks, including any
 -- delegated access configuration. Do not replace them with an owner-only guess.
 perform * from public.team_member_detail(rid,learner_id);
 return query select * from public.learning_results(rid,learner_id);
end;
$$;

create or replace function public.team_learning_roster(rid uuid)
returns table(user_id uuid,name text,role text,is_owner boolean,items_taken integer,
 correct_sum integer,total_sum integer,needs_review integer,last_attempt_at timestamptz)
language sql stable security definer set search_path='' as $$
 select member.user_id,member.name,member.role,member.is_owner,
   stats.items_taken,stats.correct_sum,stats.total_sum,stats.needs_review,stats.last_attempt_at
 from public.team_roster(rid) member
 cross join lateral (
   select count(*)::integer items_taken,coalesce(sum(r.correct),0)::integer correct_sum,
     coalesce(sum(r.total),0)::integer total_sum,
     count(*) filter(where r.needs_review or r.correct::numeric/r.total<0.8)::integer needs_review,
     max(r.created_at) last_attempt_at
   from public.learning_results(rid,member.user_id) r
 ) stats
 order by member.is_owner desc,member.name,member.user_id;
$$;
revoke all on function public.get_quiz_progress(uuid),public.team_member_progress(uuid,uuid),public.team_learning_roster(uuid) from public,anon,authenticated;
grant execute on function public.get_quiz_progress(uuid),public.team_member_progress(uuid,uuid),public.team_learning_roster(uuid) to authenticated;
commit;


-- ===== 027_employee_quiz_counts.sql =====
-- Reporting only. Preserve existing Team permissions and all recorded results.
begin;
create or replace function public.team_member_print_progress(rid uuid, learner_id uuid)
returns table(menu_item_id uuid,item_name text,correct integer,total integer,created_at timestamptz,needs_review boolean,attempt_count integer)
language plpgsql stable security definer set search_path='' as $$
begin
 -- The existing endpoint checks both manager access and learner membership.
 return query
 select r.menu_item_id,r.item_name,r.correct,r.total,r.created_at,r.needs_review,
   (select count(*)::integer from public.quiz_attempts a
    where a.user_id=learner_id and a.menu_item_id=r.menu_item_id and a.total>0)
 from public.team_member_progress(rid,learner_id) r;
end;
$$;
revoke all on function public.team_member_print_progress(uuid,uuid) from public,anon,authenticated;
grant execute on function public.team_member_print_progress(uuid,uuid) to authenticated;
commit;


-- ===== 028_access_codes_and_roles.sql =====
-- Applied by hand in Supabase on 29 September 2026, before this repository
-- kept a record of it. Recorded here so the schema can be rebuilt from this
-- folder. Issued at the time as `026_access.sql`; renumbered because those numbers
-- were later taken by other migrations.

-- 026_access.sql
-- Per-person access. This migration changes NO behaviour on its own.
-- can_manage() is true for the owner, and the owner is the only person
-- who can change anything today, so after this runs HEAT works exactly
-- as it does now. The switch happens in 027.
--
-- There is no "drop" anywhere in this file.
begin;

-- 1. Where a person's chips are stored. Empty for everyone, which is
--    read-only -- what every member has today.
alter table public.restaurant_members
  add column if not exists access text[] not null default '{}';

-- 2. Only these five words are ever allowed in that column. A typo
--    is rejected by the database rather than quietly granting nothing.
alter table public.restaurant_members
  add constraint restaurant_members_access_valid
  check (access <@ array['library','words','standards','preshift','team']::text[]);

-- 3. The one question every permission in HEAT will ask from now on.
--    Owner: always yes. Everyone else: yes if they hold that chip.
create or replace function public.can_manage(rid uuid, area text)
returns boolean language sql stable security definer set search_path = '' as $$
  select public.is_restaurant_owner(rid) or exists (
    select 1 from public.restaurant_members
    where restaurant_id = rid
      and user_id = (select auth.uid())
      and area = any(access)
  );
$$;
revoke all on function public.can_manage(uuid, text) from public, anon;
grant execute on function public.can_manage(uuid, text) to authenticated;

-- 4. What the signed-in person holds, so the app knows which tabs to draw.
create or replace function public.my_access(rid uuid)
returns text[] language sql stable security definer set search_path = '' as $$
  select case
    when public.is_restaurant_owner(rid)
      then array['library','words','standards','preshift','team']::text[]
    else coalesce(
      (select access from public.restaurant_members
       where restaurant_id = rid and user_id = (select auth.uid())), '{}')
  end;
$$;
revoke all on function public.my_access(uuid) from public, anon;
grant execute on function public.my_access(uuid) to authenticated;

commit;


-- ===== 029_access_content_policies.sql =====
-- Applied by hand in Supabase on 29 September 2026, before this repository
-- kept a record of it. Recorded here so the schema can be rebuilt from this
-- folder. Issued at the time as `027_access_content.sql`; renumbered because those numbers
-- were later taken by other migrations.

-- 027_access_content.sql
-- Repoints every write rule from "are you the owner?" to "can you manage
-- this area?". You are the owner, so nothing changes for you. Nobody holds
-- a chip yet, so nothing changes for anyone else either -- chips cannot be
-- handed out until the Team screen ships. This is safe to run today.
--
-- Every drop in this file is "drop policy", immediately followed by a
-- "create policy" of the same name. A policy is a permission rule, not data.
-- No table, column or row is removed anywhere in this file.
--
-- Run 026_access.sql before this one.
begin;

-- ---------- CONTENT LIBRARY: dishes, and their allergens ----------
drop policy "Owner adds menu" on public.menu_items;
create policy "Owner adds menu" on public.menu_items for insert to authenticated
  with check (public.can_manage(restaurant_id, 'library'));

drop policy "Owner edits menu" on public.menu_items;
create policy "Owner edits menu" on public.menu_items for update to authenticated
  using (public.can_manage(restaurant_id, 'library'))
  with check (public.can_manage(restaurant_id, 'library'));

drop policy "Owner deletes menu" on public.menu_items;
create policy "Owner deletes menu" on public.menu_items for delete to authenticated
  using (public.can_manage(restaurant_id, 'library'));

drop policy "Owner writes sections" on public.menu_sections;
create policy "Owner writes sections" on public.menu_sections for all to authenticated
  using (public.can_manage(restaurant_id, 'library'))
  with check (public.can_manage(restaurant_id, 'library'));

drop policy "Owner writes categories" on public.menu_categories;
create policy "Owner writes categories" on public.menu_categories for all to authenticated
  using (public.can_manage(restaurant_id, 'library'))
  with check (public.can_manage(restaurant_id, 'library'));

-- ---------- WORDS & GUIDES ----------
drop policy "Owner adds words" on public.glossary_terms;
create policy "Owner adds words" on public.glossary_terms for insert to authenticated
  with check (public.can_manage(restaurant_id, 'words') and created_by = (select auth.uid()));

drop policy "Owner edits words" on public.glossary_terms;
create policy "Owner edits words" on public.glossary_terms for update to authenticated
  using (public.can_manage(restaurant_id, 'words'))
  with check (public.can_manage(restaurant_id, 'words'));

drop policy "Owner deletes words" on public.glossary_terms;
create policy "Owner deletes words" on public.glossary_terms for delete to authenticated
  using (public.can_manage(restaurant_id, 'words'));

-- ---------- STANDARDS ----------
drop policy "Owner adds standards" on public.sops;
create policy "Owner adds standards" on public.sops for insert to authenticated
  with check (public.can_manage(restaurant_id, 'standards') and created_by = (select auth.uid()));

drop policy "Owner edits standards" on public.sops;
create policy "Owner edits standards" on public.sops for update to authenticated
  using (public.can_manage(restaurant_id, 'standards'))
  with check (public.can_manage(restaurant_id, 'standards'));

drop policy "Owner deletes standards" on public.sops;
create policy "Owner deletes standards" on public.sops for delete to authenticated
  using (public.can_manage(restaurant_id, 'standards'));

-- ---------- PRE-SHIFT: the note ----------
drop policy "Owner adds shift notes" on public.shift_notes;
create policy "Owner adds shift notes" on public.shift_notes for insert to authenticated
  with check (public.can_manage(restaurant_id, 'preshift') and posted_by = (select auth.uid()));

drop policy "Owner edits shift notes" on public.shift_notes;
create policy "Owner edits shift notes" on public.shift_notes for update to authenticated
  using (public.can_manage(restaurant_id, 'preshift'))
  with check (public.can_manage(restaurant_id, 'preshift') and posted_by = (select auth.uid()));

drop policy "Owner deletes shift notes" on public.shift_notes;
create policy "Owner deletes shift notes" on public.shift_notes for delete to authenticated
  using (public.can_manage(restaurant_id, 'preshift'));

-- ---------- PRE-SHIFT: the 86 board ----------
drop policy "Owner adds shift entries" on public.shift_board_entries;
create policy "Owner adds shift entries" on public.shift_board_entries for insert to authenticated
  with check (exists (select 1 from public.shift_notes n
    where n.id = shift_note_id and public.can_manage(n.restaurant_id, 'preshift')));

drop policy "Owner edits shift entries" on public.shift_board_entries;
create policy "Owner edits shift entries" on public.shift_board_entries for update to authenticated
  using (exists (select 1 from public.shift_notes n
    where n.id = shift_note_id and public.can_manage(n.restaurant_id, 'preshift')))
  with check (exists (select 1 from public.shift_notes n
    where n.id = shift_note_id and public.can_manage(n.restaurant_id, 'preshift')));

drop policy "Owner deletes shift entries" on public.shift_board_entries;
create policy "Owner deletes shift entries" on public.shift_board_entries for delete to authenticated
  using (exists (select 1 from public.shift_notes n
    where n.id = shift_note_id and public.can_manage(n.restaurant_id, 'preshift')));

-- ---------- PRE-SHIFT: the focus items ----------
drop policy "Owner adds shift focus" on public.shift_focus_items;
create policy "Owner adds shift focus" on public.shift_focus_items for insert to authenticated
  with check (exists (select 1 from public.shift_notes n
    where n.id = shift_note_id and public.can_manage(n.restaurant_id, 'preshift')));

drop policy "Owner edits shift focus" on public.shift_focus_items;
create policy "Owner edits shift focus" on public.shift_focus_items for update to authenticated
  using (exists (select 1 from public.shift_notes n
    where n.id = shift_note_id and public.can_manage(n.restaurant_id, 'preshift')))
  with check (exists (select 1 from public.shift_notes n
    where n.id = shift_note_id and public.can_manage(n.restaurant_id, 'preshift')));

drop policy "Owner deletes shift focus" on public.shift_focus_items;
create policy "Owner deletes shift focus" on public.shift_focus_items for delete to authenticated
  using (exists (select 1 from public.shift_notes n
    where n.id = shift_note_id and public.can_manage(n.restaurant_id, 'preshift')));

-- ---------- PHOTOS ----------
-- One bucket serves dish photos and guide photos, so either chip may upload.
drop policy "Managers upload restaurant photos" on storage.objects;
create policy "Managers upload restaurant photos" on storage.objects for insert to authenticated
with check (bucket_id = 'menu-photos' and exists (
  select 1 from public.restaurants r
  where r.id::text = (storage.foldername(storage.objects.name))[1]
    and (public.can_manage(r.id, 'library') or public.can_manage(r.id, 'words'))
));

drop policy "Managers clean up uploads" on storage.objects;
create policy "Managers clean up uploads" on storage.objects for delete to authenticated
using (bucket_id = 'menu-photos' and exists (
  select 1 from public.restaurants r
  where r.id::text = (storage.foldername(storage.objects.name))[1]
    and (public.can_manage(r.id, 'library') or public.can_manage(r.id, 'words'))
));

-- ---------- The posting function ----------
-- Unchanged except the first check. This function does not bypass security
-- (it runs as the signed-in person), so the line below is the friendly error
-- message, not the lock -- the real lock is the policies above.
create or replace function public.save_preshift_board(
  rid uuid, board_date date, board_note text, focus_ids uuid[], board_entries jsonb
) returns uuid
language plpgsql security invoker set search_path = '' as $$
declare board_id uuid;
begin
  if not public.can_manage(rid, 'preshift') then
    raise exception 'You do not have access to the pre-shift board.' using errcode = '42501';
  end if;
  if board_date is distinct from current_date then
    raise exception 'The service day has changed. Reload today''s board before posting.';
  end if;
  if board_entries is null or jsonb_typeof(board_entries) <> 'array' then
    raise exception 'Board entries must be a list.' using errcode = '23514';
  end if;
  if coalesce(array_length(focus_ids, 1), 0) > 10 then
    raise exception 'A board can hold up to 10 focus items.' using errcode = '23514';
  end if;

  insert into public.shift_notes(restaurant_id, service_date, note, focus_item_id, posted_by)
  values(rid, current_date, board_note, focus_ids[1], auth.uid())
  on conflict (restaurant_id, service_date) do update
  set note = excluded.note, focus_item_id = excluded.focus_item_id, posted_by = excluded.posted_by
  returning id into board_id;

  delete from public.shift_focus_items where shift_note_id = board_id;
  insert into public.shift_focus_items(shift_note_id, menu_item_id, sort_order)
  select board_id, f.id, min(f.ord)::smallint
  from unnest(focus_ids) with ordinality as f(id, ord)
  where f.id is not null
  group by f.id;

  delete from public.shift_board_entries where shift_note_id = board_id;
  insert into public.shift_board_entries(shift_note_id, menu_item_id, status, detail)
  select board_id, e.menu_item_id, e.status, coalesce(e.detail, '')
  from jsonb_to_recordset(board_entries) as e(menu_item_id uuid, status text, detail text);
  return board_id;
end;
$$;

commit;


-- ===== 030_access_team_functions.sql =====
-- Applied by hand in Supabase on 29 September 2026, before this repository
-- kept a record of it. Recorded here so the schema can be rebuilt from this
-- folder. Issued at the time as `028_access_team.sql`; renumbered because those numbers
-- were later taken by other migrations.

-- 028_access_team.sql
-- The team side. Eight existing functions stop asking "are you the owner?"
-- and start asking "can you manage the team?", plus two new ones: reading
-- everyone's chips, and setting them.
--
-- There is no "drop" anywhere in this file.
-- Run 026_access.sql and 027_access_content.sql before this one.
begin;

-- ---------- Inviting ----------
create or replace function public.create_employee_invite(rid uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare new_token uuid;
begin
  if not public.can_manage(rid, 'team') then raise exception 'You do not have access to the team.'; end if;
  insert into public.restaurant_invites(restaurant_id) values(rid)
  on conflict (restaurant_id) do update set token = gen_random_uuid(), expires_at = now() + interval '7 days'
  returning token into new_token;
  return new_token;
end;
$$;

-- ---------- Reading the team ----------
create or replace function public.team_roster(rid uuid)
returns table(user_id uuid,name text,role text,is_owner boolean,items_taken integer,correct_sum integer,total_sum integer,needs_review integer,last_attempt_at timestamptz)
language plpgsql stable security definer set search_path='' as $$
begin
 if not public.can_manage(rid,'team') then raise exception 'You do not have access to the team.'; end if;
 return query
 with members as (
  select r.owner_id as uid from public.restaurants r where r.id=rid
  union select rm.user_id from public.restaurant_members rm where rm.restaurant_id=rid
 )
 select u.id,coalesce(nullif(trim(p.display_name),''),nullif(trim(u.raw_user_meta_data->>'display_name'),''),u.email::text,u.id::text),
 coalesce(p.role,case when u.id=r.owner_id then 'Manager' else 'Server' end),u.id=r.owner_id,
 s.items_taken,s.correct_sum,s.total_sum,s.needs_review,s.last_attempt_at
 from members mm join auth.users u on u.id=mm.uid join public.restaurants r on r.id=rid
 left join public.member_profiles p on p.restaurant_id=rid and p.user_id=u.id
 cross join lateral (
  select count(*)::integer as items_taken,coalesce(sum(a.correct),0)::integer as correct_sum,
  coalesce(sum(a.total),0)::integer as total_sum,count(*) filter(where a.correct::numeric/a.total<0.8)::integer as needs_review,
  max(a.created_at) as last_attempt_at
  from (
   select distinct on (a.menu_item_id) a.correct,a.total,a.created_at
   from public.quiz_attempts a join public.menu_items m on m.id=a.menu_item_id
   where a.user_id=u.id and m.restaurant_id=rid and a.menu_updated_at=m.updated_at
   order by a.menu_item_id,a.created_at desc,a.id desc
  ) a
 ) s
 order by (u.id=r.owner_id) desc,2,u.id;
end $$;

create or replace function public.team_member_detail(rid uuid,learner_id uuid)
returns table(menu_item_id uuid,item_name text,correct integer,total integer,created_at timestamptz)
language plpgsql stable security definer set search_path='' as $$
begin
 if not public.can_manage(rid,'team') then raise exception 'You do not have access to the team.'; end if;
 if not exists(select 1 from public.restaurants r where r.id=rid and r.owner_id=learner_id)
 and not exists(select 1 from public.restaurant_members rm where rm.restaurant_id=rid and rm.user_id=learner_id) then raise exception 'Team member unavailable'; end if;
 return query select distinct on (a.menu_item_id) a.menu_item_id,m.name,a.correct,a.total,a.created_at
 from public.quiz_attempts a join public.menu_items m on m.id=a.menu_item_id
 where a.user_id=learner_id and m.restaurant_id=rid and a.menu_updated_at=m.updated_at
 order by a.menu_item_id,a.created_at desc,a.id desc;
end $$;

create or replace function public.team_member_assignments(rid uuid,learner_id uuid)
returns table(id uuid,menu_item_id uuid,item_name text,note text,due_on date,created_at timestamptz)
language plpgsql stable security definer set search_path='' as $$
begin
 if not public.can_manage(rid,'team') then raise exception 'You do not have access to the team.'; end if;
 if not exists(select 1 from public.restaurants r where r.id=rid and r.owner_id=learner_id)
 and not exists(select 1 from public.restaurant_members rm where rm.restaurant_id=rid and rm.user_id=learner_id) then raise exception 'Team member unavailable'; end if;
 return query select a.id,a.menu_item_id,m.name,a.note,a.due_on,a.created_at
 from public.assignments a join public.menu_items m on m.id=a.menu_item_id and m.restaurant_id=rid
 where a.restaurant_id=rid and a.user_id=learner_id order by a.due_on nulls last,a.created_at,a.id;
end $$;

-- ---------- Changing the team ----------
create or replace function public.set_member_profile(rid uuid,learner_id uuid,name text,member_role text) returns void
language plpgsql security definer set search_path='' as $$
begin
 if not public.can_manage(rid,'team') then raise exception 'You do not have access to the team.'; end if;
 perform 1 from public.restaurant_members rm where rm.restaurant_id=rid and rm.user_id=learner_id for update;
 if not found and not exists(select 1 from public.restaurants r where r.id=rid and r.owner_id=learner_id) then raise exception 'Team member unavailable'; end if;
 insert into public.member_profiles(restaurant_id,user_id,display_name,role) values(rid,learner_id,trim(name),member_role)
 on conflict(restaurant_id,user_id) do update set display_name=excluded.display_name,role=excluded.role,updated_at=clock_timestamp();
end $$;

create or replace function public.assign_menu_items(rid uuid,learner_id uuid,mids uuid[],note text default '',due date default null) returns void
language plpgsql security definer set search_path='' as $$
begin
 if not public.can_manage(rid,'team') then raise exception 'You do not have access to the team.'; end if;
 perform 1 from public.restaurant_members rm where rm.restaurant_id=rid and rm.user_id=learner_id for update;
 if not found and not exists(select 1 from public.restaurants r where r.id=rid and r.owner_id=learner_id) then raise exception 'Team member unavailable'; end if;
 if mids is null or cardinality(mids)=0 then raise exception 'Choose at least one menu item'; end if;
 if exists(select 1 from unnest(mids) as wanted(mid) where not exists(select 1 from public.menu_items m where m.id=wanted.mid and m.restaurant_id=rid)) then raise exception 'Every menu item must belong to this restaurant'; end if;
 insert into public.assignments(restaurant_id,user_id,menu_item_id,note,due_on,assigned_by)
 select rid,learner_id,wanted.mid,assign_menu_items.note,due,auth.uid() from (select distinct unnest(mids) as mid) wanted
 on conflict(user_id,menu_item_id) do update set note=excluded.note,due_on=excluded.due_on,assigned_by=excluded.assigned_by;
end $$;

create or replace function public.remove_assignment(assignment_id uuid) returns void
language plpgsql security definer set search_path='' as $$
begin
 if not public.can_manage((select a.restaurant_id from public.assignments a where a.id=assignment_id),'team') then raise exception 'You do not have access to the team.'; end if;
 delete from public.assignments where id=assignment_id;
end $$;

create or replace function public.remove_team_member(rid uuid,learner_id uuid) returns void
language plpgsql security definer set search_path='' as $$
begin
 if not public.can_manage(rid,'team') then raise exception 'You do not have access to the team.'; end if;
 if exists(select 1 from public.restaurants r where r.id=rid and r.owner_id=learner_id) then raise exception 'The restaurant owner cannot be removed'; end if;
 delete from public.restaurant_members where restaurant_id=rid and user_id=learner_id;
 if not found then raise exception 'Team member unavailable'; end if;
end $$;

-- ---------- NEW: reading everyone's chips ----------
create or replace function public.team_access(rid uuid)
returns table(user_id uuid, access text[])
language plpgsql stable security definer set search_path='' as $$
begin
  if not public.can_manage(rid,'team') then raise exception 'You do not have access to the team.'; end if;
  return query select rm.user_id, rm.access from public.restaurant_members rm where rm.restaurant_id = rid;
end $$;
revoke all on function public.team_access(uuid) from public, anon;
grant execute on function public.team_access(uuid) to authenticated;

-- ---------- NEW: setting somebody's chips ----------
-- Four refusals, in order. Read these as the rules of the system.
create or replace function public.set_member_access(rid uuid, learner_id uuid, new_access text[])
returns void language plpgsql security definer set search_path='' as $$
declare wanted text[]; mine text[];
begin
  -- 1. You need the team chip to be here at all.
  if not public.can_manage(rid,'team') then
    raise exception 'You do not have access to the team.'; end if;

  -- 2. The owner's access is not a setting. Nobody edits it, including the owner.
  if exists(select 1 from public.restaurants r where r.id=rid and r.owner_id=learner_id) then
    raise exception 'The restaurant owner always has full access.'; end if;

  -- 3. Nobody edits their own chips -- otherwise the team chip is a promotion to everything.
  if learner_id = (select auth.uid()) then
    raise exception 'You cannot change your own access. Ask the owner or a GM.'; end if;

  perform 1 from public.restaurant_members rm
    where rm.restaurant_id=rid and rm.user_id=learner_id for update;
  if not found then raise exception 'Team member unavailable'; end if;

  wanted := array_remove(coalesce(new_access, '{}'), null);
  mine := public.my_access(rid);

  -- 4. You can only hand out what you hold yourself.
  if not (wanted <@ mine) then
    raise exception 'You can only give access that you have yourself.'; end if;

  update public.restaurant_members set access = wanted
   where restaurant_id=rid and user_id=learner_id;
end $$;
revoke all on function public.set_member_access(uuid, uuid, text[]) from public, anon;
grant execute on function public.set_member_access(uuid, uuid, text[]) to authenticated;

commit;


-- ===== 031_card_fields.sql =====
-- Run once in the Supabase SQL editor. Step 1 of letting managers choose the fields on each card.
--
-- After this, every restaurant can keep its own settings for the extra fields on its Food, Cocktail
-- and Wine & Sake cards: hide a field the app ships with, add fields of its own, and delete a field
-- it made. Nothing on screen changes until the app files are updated, and nothing here touches a
-- dish, a photo, a quiz, a score, a word or a team member. No existing row is changed or removed.
--
-- How it works, in plain words:
--   * A restaurant with no rows here sees exactly the fields it sees today. A row only exists
--     once a manager changes something, so a brand-new restaurant needs no setup.
--   * What staff typed into a field stays on each dish (menu_items.details), under the field's
--     key. Hiding a field never touches it, so "Show again" brings every answer back.
--   * Fields the app ships with ("custom" = false) can be hidden or shown, never deleted: the
--     quiz builder reads some of them (method, glassware, region, producer).
--   * Fields a manager makes ("custom" = true) get a key that starts with "x_", so they can never
--     collide with a built-in one. The key is what is stored, so renaming a label never loses data.
--   * Deleting is only possible for a custom field that is already hidden, and it goes through
--     delete_card_field() below, which erases the field and its answers together or not at all.
begin;

create table public.card_fields (
  restaurant_id uuid not null references public.restaurants(id) on delete cascade,
  content_type text not null check (content_type in ('food','cocktails','wine')),
  field_key text not null check (field_key ~ '^[a-z][a-z0-9_]{0,39}$'),
  custom boolean not null default false,
  label text check (label is null or char_length(btrim(label)) between 1 and 40),
  kind text not null default 'line' check (kind in ('line','text')),
  hidden boolean not null default false,
  on_card boolean not null default true,
  show_team boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (restaurant_id, content_type, field_key),
  -- a field a manager made needs a name and an "x_" key; one the app ships with has neither
  check (custom = (field_key like 'x\_%')),
  check (not custom or label is not null)
);

alter table public.card_fields enable row level security;

create policy "Members read card fields" on public.card_fields for select to authenticated
  using (public.can_read_restaurant(restaurant_id));
create policy "Managers write card fields" on public.card_fields for all to authenticated
  using (public.can_manage(restaurant_id, 'library'))
  with check (public.can_manage(restaurant_id, 'library'));

revoke all on public.card_fields from public, anon, authenticated;
grant select, insert, update, delete on public.card_fields to authenticated;

-- Deleting a field you made, for good: the field and its answers on every dish, together.
-- Runs as the signed-in person, so the policies above still apply; the first check is the
-- friendly error message, not the lock. Returns how many dishes had an answer erased.
create or replace function public.delete_card_field(rid uuid, ctype text, fkey text)
returns integer
language plpgsql security invoker set search_path = '' as $$
declare cleaned integer;
begin
  if not public.can_manage(rid, 'library') then
    raise exception 'You do not have access to the content library.' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.card_fields f
    where f.restaurant_id = rid and f.content_type = ctype and f.field_key = fkey
      and f.custom and f.hidden
  ) then
    raise exception 'Only a hidden field you created can be deleted.' using errcode = '23514';
  end if;

  update public.menu_items m
  set details = m.details - fkey
  where m.restaurant_id = rid and m.content_type = ctype and m.details ? fkey;
  get diagnostics cleaned = row_count;

  delete from public.card_fields f
  where f.restaurant_id = rid and f.content_type = ctype and f.field_key = fkey;

  return cleaned;
end;
$$;

revoke all on function public.delete_card_field(uuid, text, text) from public, anon;
grant execute on function public.delete_card_field(uuid, text, text) to authenticated;

commit;


-- ===== 032_team_member_email.sql =====
-- 032_team_member_email.sql
-- A manager who can manage the team can read the sign-in email of one person
-- on that team, so they can tell someone which email they signed up with.
-- Nothing else about auth.users is exposed, and nobody else can call it.

begin;

create or replace function public.team_member_email(rid uuid, learner_id uuid)
returns text
language plpgsql stable security definer set search_path='' as $$
begin
  if not public.can_manage(rid,'team') then
    raise exception 'You do not have access to the team.';
  end if;
  if not exists (select 1 from public.restaurants r where r.id=rid and r.owner_id=learner_id)
     and not exists (select 1 from public.restaurant_members m where m.restaurant_id=rid and m.user_id=learner_id) then
    raise exception 'Team member unavailable';
  end if;
  return (select u.email::text from auth.users u where u.id=learner_id);
end $$;

revoke all on function public.team_member_email(uuid, uuid) from public, anon;
grant execute on function public.team_member_email(uuid, uuid) to authenticated;

commit;


-- ===== 033_checklists.sql =====
-- 033_checklists.sql
-- Checklists: saved jobs, who is working today, who does which job, and the ticks.
--
-- Additive only. Four new tables and a handful of new functions. There is no
-- "drop" anywhere in this file and nothing that already exists is changed.
-- Safe to run today: until the Checklists screens ship, nothing in the app reads these.
--
-- Who can do what
--   * Everyone on the team can READ the posted shift (so each person sees the whole floor).
--   * Managing (saved jobs, who is working, assigning, posting) needs the existing
--     "Pre-shift" chip -- the same one that lets someone post the pre-shift board.
--     The owner always has it. No new chip, so nothing changes on the Team screen.
--   * Staff can only touch their OWN job, and only through the small functions at
--     the bottom: tick a step, mark the job done, leave a note.
--
-- Steps are copied onto each assignment when it is made. That way, editing a saved job
-- later never rewrites what happened on a past shift, and one-off jobs need no saved job.
begin;

-- ---------- Saved jobs (the library the manager builds once) ----------
create table public.checklist_jobs (
  id uuid primary key default gen_random_uuid(),
  restaurant_id uuid not null references public.restaurants(id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 80),
  group_name text not null default '' check (char_length(group_name) <= 60),
  steps text[] not null default '{}' check (cardinality(steps) <= 30),
  sort_order integer not null default 0,
  archived boolean not null default false,
  updated_at timestamptz not null default now(),
  created_by uuid not null default auth.uid() references auth.users(id)
);
create unique index checklist_jobs_one_per_name
  on public.checklist_jobs (restaurant_id, lower(btrim(name))) where not archived;

-- ---------- A shift: one service on one day ----------
create table public.checklist_shifts (
  id uuid primary key default gen_random_uuid(),
  restaurant_id uuid not null references public.restaurants(id) on delete cascade,
  shift_date date not null default current_date,
  label text not null default 'Service' check (char_length(btrim(label)) between 1 and 40),
  -- draft: the manager is still choosing. posted: the floor can see it. closed: finished.
  status text not null default 'draft' check (status in ('draft', 'posted', 'closed')),
  posted_at timestamptz,
  created_at timestamptz not null default now(),
  created_by uuid not null default auth.uid() references auth.users(id),
  unique (restaurant_id, shift_date, label)
);

-- ---------- Who is working that shift ----------
create table public.checklist_floor (
  shift_id uuid not null references public.checklist_shifts(id) on delete cascade,
  restaurant_id uuid not null references public.restaurants(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  primary key (shift_id, user_id)
);

-- ---------- Who does which job, and how far they got ----------
create table public.checklist_assignments (
  id uuid primary key default gen_random_uuid(),
  shift_id uuid not null references public.checklist_shifts(id) on delete cascade,
  restaurant_id uuid not null references public.restaurants(id) on delete cascade,
  -- Empty for a one-off job made just for today.
  job_id uuid references public.checklist_jobs(id) on delete set null,
  title text not null check (char_length(btrim(title)) between 1 and 80),
  group_name text not null default '' check (char_length(group_name) <= 60),
  steps text[] not null default '{}' check (cardinality(steps) <= 30),
  user_id uuid references auth.users(id) on delete set null,
  -- The manager chose this name by hand, so "Shuffle again" must leave it alone.
  locked boolean not null default false,
  -- Positions (starting at 1) of the steps that have been ticked.
  steps_done integer[] not null default '{}',
  done_at timestamptz,
  note text not null default '' check (char_length(note) <= 300),
  sort_order integer not null default 0
);
create index checklist_assignments_by_shift on public.checklist_assignments (shift_id);
create index checklist_assignments_by_person on public.checklist_assignments (restaurant_id, user_id);

-- ---------- Locks ----------
alter table public.checklist_jobs enable row level security;
alter table public.checklist_shifts enable row level security;
alter table public.checklist_floor enable row level security;
alter table public.checklist_assignments enable row level security;

-- Saved jobs: managers see all; staff see the active ones.
create policy "Read saved jobs" on public.checklist_jobs for select to authenticated
using (public.can_manage(restaurant_id, 'preshift')
       or (public.can_read_restaurant(restaurant_id) and not archived));
create policy "Managers add saved jobs" on public.checklist_jobs for insert to authenticated
with check (public.can_manage(restaurant_id, 'preshift') and created_by = (select auth.uid()));
create policy "Managers edit saved jobs" on public.checklist_jobs for update to authenticated
using (public.can_manage(restaurant_id, 'preshift'))
with check (public.can_manage(restaurant_id, 'preshift'));
create policy "Managers delete saved jobs" on public.checklist_jobs for delete to authenticated
using (public.can_manage(restaurant_id, 'preshift'));

-- Shifts: managers see all; staff see a shift once it is posted.
create policy "Read shifts" on public.checklist_shifts for select to authenticated
using (public.can_manage(restaurant_id, 'preshift')
       or (public.can_read_restaurant(restaurant_id) and status <> 'draft'));
create policy "Managers add shifts" on public.checklist_shifts for insert to authenticated
with check (public.can_manage(restaurant_id, 'preshift') and created_by = (select auth.uid()));
create policy "Managers edit shifts" on public.checklist_shifts for update to authenticated
using (public.can_manage(restaurant_id, 'preshift'))
with check (public.can_manage(restaurant_id, 'preshift'));
create policy "Managers delete shifts" on public.checklist_shifts for delete to authenticated
using (public.can_manage(restaurant_id, 'preshift'));

-- Who is working: same rule as the shift it belongs to.
create policy "Read the floor" on public.checklist_floor for select to authenticated
using (public.can_manage(restaurant_id, 'preshift')
       or (public.can_read_restaurant(restaurant_id) and exists (
            select 1 from public.checklist_shifts s
            where s.id = shift_id and s.status <> 'draft')));
create policy "Managers add to the floor" on public.checklist_floor for insert to authenticated
with check (public.can_manage(restaurant_id, 'preshift'));
create policy "Managers edit the floor" on public.checklist_floor for update to authenticated
using (public.can_manage(restaurant_id, 'preshift'))
with check (public.can_manage(restaurant_id, 'preshift'));
create policy "Managers remove from the floor" on public.checklist_floor for delete to authenticated
using (public.can_manage(restaurant_id, 'preshift'));

-- Assignments: same rule. Staff never write here directly (see the functions below).
create policy "Read assignments" on public.checklist_assignments for select to authenticated
using (public.can_manage(restaurant_id, 'preshift')
       or (public.can_read_restaurant(restaurant_id) and exists (
            select 1 from public.checklist_shifts s
            where s.id = shift_id and s.status <> 'draft')));
create policy "Managers add assignments" on public.checklist_assignments for insert to authenticated
with check (public.can_manage(restaurant_id, 'preshift'));
create policy "Managers edit assignments" on public.checklist_assignments for update to authenticated
using (public.can_manage(restaurant_id, 'preshift'))
with check (public.can_manage(restaurant_id, 'preshift'));
create policy "Managers delete assignments" on public.checklist_assignments for delete to authenticated
using (public.can_manage(restaurant_id, 'preshift'));

revoke all on public.checklist_jobs, public.checklist_shifts,
  public.checklist_floor, public.checklist_assignments from public, anon, authenticated;
grant select, insert, update, delete on public.checklist_jobs, public.checklist_shifts,
  public.checklist_floor, public.checklist_assignments to authenticated;

-- ---------- Names for the floor ----------
-- Everyone on the team can see who is who on a posted shift, but the normal team list is
-- for managers only. This returns just a first name-level label for each person -- no
-- email, no quiz results.
create or replace function public.checklist_names(rid uuid)
returns table(user_id uuid, name text)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.can_read_restaurant(rid) then
    raise exception 'You do not have access to this restaurant.' using errcode = '42501';
  end if;
  return query
  with members as (
    select r.owner_id as uid from public.restaurants r where r.id = rid
    union select rm.user_id from public.restaurant_members rm where rm.restaurant_id = rid
  )
  select u.id,
    coalesce(nullif(trim(p.display_name), ''),
             nullif(trim(u.raw_user_meta_data->>'display_name'), ''),
             split_part(u.email::text, '@', 1))
  from members m
  join auth.users u on u.id = m.uid
  left join public.member_profiles p on p.restaurant_id = rid and p.user_id = u.id
  order by 2, 1;
end $$;
revoke all on function public.checklist_names(uuid) from public, anon;
grant execute on function public.checklist_names(uuid) to authenticated;

-- ---------- What staff can do to their own job ----------
-- Tick or untick one step of the job that is assigned to me, on a posted shift.
create or replace function public.checklist_tick_step(aid uuid, step integer, ticked boolean)
returns void
language plpgsql security definer set search_path = '' as $$
declare a public.checklist_assignments; s public.checklist_shifts;
begin
  select * into a from public.checklist_assignments where id = aid;
  if not found or a.user_id is distinct from (select auth.uid()) then
    raise exception 'That job is not yours.' using errcode = '42501';
  end if;
  select * into s from public.checklist_shifts where id = a.shift_id;
  if s.status <> 'posted' then raise exception 'This shift is not open.'; end if;
  if a.done_at is not null then raise exception 'This job is already done.'; end if;
  if step < 1 or step > cardinality(a.steps) then raise exception 'There is no such step.'; end if;
  update public.checklist_assignments
  set steps_done = case
    when ticked then (select coalesce(array_agg(distinct x order by x), '{}') from unnest(steps_done || step) x)
    else array_remove(steps_done, step) end
  where id = aid;
end $$;
revoke all on function public.checklist_tick_step(uuid, integer, boolean) from public, anon;
grant execute on function public.checklist_tick_step(uuid, integer, boolean) to authenticated;

-- Mark my job done (or take it back), with an optional note for the manager.
create or replace function public.checklist_finish_job(aid uuid, finished boolean, job_note text default '')
returns timestamptz
language plpgsql security definer set search_path = '' as $$
declare a public.checklist_assignments; s public.checklist_shifts; stamp timestamptz;
begin
  select * into a from public.checklist_assignments where id = aid;
  if not found or a.user_id is distinct from (select auth.uid()) then
    raise exception 'That job is not yours.' using errcode = '42501';
  end if;
  select * into s from public.checklist_shifts where id = a.shift_id;
  if s.status <> 'posted' then raise exception 'This shift is not open.'; end if;
  stamp := case when finished then now() else null end;
  update public.checklist_assignments
  set done_at = stamp,
      note = left(coalesce(btrim(job_note), ''), 300)
  where id = aid;
  return stamp;
end $$;
revoke all on function public.checklist_finish_job(uuid, boolean, text) from public, anon;
grant execute on function public.checklist_finish_job(uuid, boolean, text) to authenticated;

commit;


-- ===== 034_trial_and_demo.sql =====
-- Run once, after 033, BEFORE deploying the version of HEAT with the public site (/, /demo, /trial).
-- It adds two ways in besides an access code:
--   * a free trial: anyone with a confirmed account can create one restaurant that runs 14 days;
--   * the demo kitchen: one restaurant marked is_demo that visitors join, read-only, without an account.
--
-- Nothing is dropped or rewritten. Every existing restaurant keeps trial_ends_at empty (a full account)
-- and is_demo false. create_restaurant_with_code keeps working exactly as before.
begin;

-- Empty means a full account. A date means a trial that ends then.
alter table public.restaurants add column if not exists trial_ends_at timestamptz;
-- The demo kitchen. Only the SQL editor sets this (supabase/demo-seed.sql); the app never writes it.
alter table public.restaurants add column if not exists is_demo boolean not null default false;
create unique index if not exists restaurants_one_demo on public.restaurants (is_demo) where is_demo;

-- A free trial restaurant, without an access code. One per account, so a trial can't be renewed
-- by creating another, and never for an anonymous demo visitor.
create or replace function public.start_trial_restaurant(restaurant_name text)
returns uuid
language plpgsql security definer set search_path = '' as $$
declare new_id uuid;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in first.' using errcode = '42501';
  end if;
  if coalesce((select auth.jwt() ->> 'is_anonymous')::boolean, false) then
    raise exception 'Create an account to start a free trial.' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(restaurant_name, ''))) = 0 then
    raise exception 'Give the restaurant a name.' using errcode = '23514';
  end if;
  if exists (select 1 from public.restaurants r where r.owner_id = (select auth.uid()) and r.trial_ends_at is not null) then
    raise exception 'This account has already started a free trial. Contact HEAT to add another restaurant.' using errcode = '42501';
  end if;

  insert into public.restaurants(owner_id, name, trial_ends_at)
  values ((select auth.uid()), btrim(restaurant_name), now() + interval '14 days')
  returning id into new_id;
  return new_id;
end $$;
revoke all on function public.start_trial_restaurant(text) from public, anon;
grant execute on function public.start_trial_restaurant(text) to authenticated;

-- A demo visitor joins the demo kitchen as an ordinary member with no access areas, which in HEAT
-- means read-only: they can read the menu, use the allergy check and take quizzes, and change nothing.
create or replace function public.join_demo()
returns uuid
language plpgsql security definer set search_path = '' as $$
declare rid uuid;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in first.' using errcode = '42501';
  end if;
  select id into rid from public.restaurants where is_demo;
  if rid is null then
    raise exception 'The demo kitchen is not set up.' using errcode = 'P0002';
  end if;
  insert into public.restaurant_members(restaurant_id, user_id) values (rid, (select auth.uid()))
  on conflict do nothing;
  return rid;
end $$;
revoke all on function public.join_demo() from public, anon;
grant execute on function public.join_demo() to authenticated;

commit;


-- ===== 035_organizations.sql =====
-- Run once, after 034. Groups restaurants under a brand: one organization (Osaka) with
-- several locations (Miami, Chicago...). Each location keeps its own menu, team and pre-shift.
--
-- What changes:
--   * a new organizations table, and restaurants.organization_id (empty for every existing restaurant);
--   * is_restaurant_owner() also answers yes for the organization's owner, so the brand's owner can run
--     every location without being added to each one. Every existing rule that asks "is this the owner?"
--     keeps asking exactly that; nothing changes for a restaurant that is not in an organization;
--   * functions to start an organization, add a restaurant to it, open a new location in it, and
--     copy chosen dishes from one location to another.
--
-- Nothing is dropped. No menu item, member, score or photo is changed by running this file.
begin;

create table public.organizations (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid() references auth.users(id),
  name text not null check (char_length(btrim(name)) between 1 and 100),
  created_at timestamptz not null default now()
);
alter table public.organizations enable row level security;
revoke all on public.organizations from anon, authenticated;
grant select on public.organizations to authenticated;

alter table public.restaurants
  add column if not exists organization_id uuid references public.organizations(id) on delete set null;
create index if not exists restaurants_organization on public.restaurants (organization_id);

-- The owner of a restaurant, or the owner of the organization it belongs to.
create or replace function public.is_restaurant_owner(rid uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists(
    select 1 from public.restaurants r
    left join public.organizations o on o.id = r.organization_id
    where r.id = rid and (r.owner_id = (select auth.uid()) or o.owner_id = (select auth.uid()))
  );
$$;

-- The brand's name is visible to its owner and to anyone who can open one of its locations.
create policy "Members read their organization" on public.organizations for select to authenticated
using (owner_id = (select auth.uid()) or exists (
  select 1 from public.restaurants r where r.organization_id = organizations.id and public.can_read_restaurant(r.id)
));

create or replace function public.is_anonymous() returns boolean
language sql stable set search_path = '' as $$
  select coalesce((select auth.jwt() ->> 'is_anonymous')::boolean, false);
$$;

-- Start a brand around a restaurant you own yourself.
create or replace function public.create_organization(org_name text, rid uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare new_id uuid;
begin
  if (select auth.uid()) is null or public.is_anonymous() then
    raise exception 'Sign in first.' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(org_name, ''))) = 0 then
    raise exception 'Give the brand a name.' using errcode = '23514';
  end if;
  perform 1 from public.restaurants r
  where r.id = rid and r.owner_id = (select auth.uid()) and r.organization_id is null and not r.is_demo
  for update;
  if not found then
    raise exception 'Only the owner of a restaurant that is not in a brand yet can start one from it.' using errcode = '42501';
  end if;
  insert into public.organizations(owner_id, name) values ((select auth.uid()), btrim(org_name)) returning id into new_id;
  update public.restaurants set organization_id = new_id where id = rid;
  return new_id;
end $$;

-- Bring another restaurant you own into your brand.
create or replace function public.add_restaurant_to_organization(oid uuid, rid uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not exists (select 1 from public.organizations o where o.id = oid and o.owner_id = (select auth.uid())) then
    raise exception 'Only the owner of the brand can add locations to it.' using errcode = '42501';
  end if;
  update public.restaurants set organization_id = oid
  where id = rid and owner_id = (select auth.uid()) and organization_id is null and not is_demo;
  if not found then
    raise exception 'That restaurant is not yours to add, or it already belongs to a brand.' using errcode = '42501';
  end if;
end $$;

-- Open a new location inside the brand. It starts empty: its own menu, team and pre-shift.
-- Only a brand with at least one full (not trial) location can open more, so a trial cannot be
-- stretched into several restaurants.
create or replace function public.create_location(oid uuid, location_name text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare new_id uuid;
begin
  if not exists (select 1 from public.organizations o where o.id = oid and o.owner_id = (select auth.uid())) then
    raise exception 'Only the owner of the brand can open a new location.' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(location_name, ''))) = 0 then
    raise exception 'Give the location a name.' using errcode = '23514';
  end if;
  if not exists (select 1 from public.restaurants r where r.organization_id = oid and r.trial_ends_at is null and not r.is_demo) then
    raise exception 'Opening more locations needs a full account. Contact HEAT to upgrade from the trial.' using errcode = '42501';
  end if;
  insert into public.restaurants(owner_id, name, organization_id)
  values ((select auth.uid()), btrim(location_name), oid)
  returning id into new_id;
  return new_id;
end $$;

-- Copy the chosen dishes, drinks and wines from one location of a brand into another.
-- Each copy is the target location's own from then on: changing it never touches the original.
-- A dish whose name is already in the target's library (same library, any capitalisation) is skipped.
-- Its category is created in the target when missing, and a custom quiz comes with it.
-- Photos live in storage, which SQL cannot copy, so each copy starts without one and the
-- source photo's path is returned for the app to copy across.
create or replace function public.import_menu_items(source_rid uuid, target_rid uuid, item_ids uuid[])
returns table(new_id uuid, source_id uuid, source_photo text)
language plpgsql security definer set search_path = '' as $$
declare
  src public.menu_items%rowtype;
  copy_id uuid;
begin
  if source_rid = target_rid then
    raise exception 'Choose a different location to import from.' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.restaurants s join public.restaurants t on t.organization_id = s.organization_id
    where s.id = source_rid and t.id = target_rid and s.organization_id is not null
  ) then
    raise exception 'Dishes can only be imported between locations of the same brand.' using errcode = '42501';
  end if;
  if not public.can_read_restaurant(source_rid) or not public.can_manage(target_rid, 'library') then
    raise exception 'You need menu access in both locations to import dishes.' using errcode = '42501';
  end if;

  for src in
    select m.* from public.menu_items m
    where m.restaurant_id = source_rid and m.id = any(coalesce(item_ids, '{}'))
    order by m.created_at
  loop
    continue when exists (
      select 1 from public.menu_items t
      where t.restaurant_id = target_rid and t.content_type = src.content_type
        and lower(btrim(t.name)) = lower(btrim(src.name))
    );

    insert into public.menu_categories(restaurant_id, content_type, name, sort_order)
    select target_rid, src.content_type, btrim(src.category),
           coalesce((select c.sort_order from public.menu_categories c
                     where c.restaurant_id = source_rid and c.content_type = src.content_type
                       and lower(btrim(c.name)) = lower(btrim(src.category)) limit 1), 900)
    where not exists (
      select 1 from public.menu_categories c
      where c.restaurant_id = target_rid and c.content_type = src.content_type
        and lower(btrim(c.name)) = lower(btrim(src.category))
    );

    -- Every column the dish has, including ones added outside these migrations, except who and when.
    copy_id := gen_random_uuid();
    insert into public.menu_items
    select * from jsonb_populate_record(null::public.menu_items, to_jsonb(src) || jsonb_build_object(
      'id', copy_id, 'restaurant_id', target_rid, 'photo_path', null,
      'created_at', now(), 'updated_at', now()));

    insert into public.menu_quiz_edits(menu_item_id, questions)
    select copy_id, q.questions from public.menu_quiz_edits q where q.menu_item_id = src.id;

    new_id := copy_id; source_id := src.id; source_photo := src.photo_path;
    return next;
  end loop;
end $$;

revoke all on function public.is_anonymous(), public.create_organization(text, uuid),
  public.add_restaurant_to_organization(uuid, uuid), public.create_location(uuid, text),
  public.import_menu_items(uuid, uuid, uuid[]) from public, anon;
grant execute on function public.is_anonymous(), public.create_organization(text, uuid),
  public.add_restaurant_to_organization(uuid, uuid), public.create_location(uuid, text),
  public.import_menu_items(uuid, uuid, uuid[]) to authenticated;

commit;


-- ===== 036_dashboards.sql =====
-- Run once, after 035. Read-only numbers for the dashboards: nothing is written, and no table,
-- policy or existing function changes. Every figure follows the rules in 026_learning_notes.md:
-- a person's latest result per current menu item, accuracy weighted by answered questions,
-- "needs review" below 80% or an updated quiz. Learners are the restaurant's members.
begin;

-- Per library (food, cocktails, wine): how much of the menu the team has covered, and how well.
-- Private: only the wrappers below may call it, after checking who is asking.
create or replace function public.location_stats(rid uuid)
returns table(content_type text, items integer, learners integer, taken integer,
  correct integer, total integer, needs_review integer, active_7d integer)
language sql stable security definer set search_path = '' as $$
  with learners as (
    select m.user_id from public.restaurant_members m where m.restaurant_id = rid
  ), results as (
    select i.content_type, r.correct, r.total, r.needs_review
    from learners l
    cross join lateral public.learning_results(rid, l.user_id) r
    join public.menu_items i on i.id = r.menu_item_id
  ), active as (
    select count(distinct a.user_id)::integer n
    from public.quiz_attempts a
    join public.menu_items i on i.id = a.menu_item_id
    join learners l on l.user_id = a.user_id
    where i.restaurant_id = rid and a.total > 0 and a.created_at > now() - interval '7 days'
  )
  select t.kind,
    (select count(*) from public.menu_items i where i.restaurant_id = rid and i.content_type = t.kind)::integer,
    (select count(*) from learners)::integer,
    (select count(*) from results r where r.content_type = t.kind)::integer,
    (select coalesce(sum(r.correct), 0) from results r where r.content_type = t.kind)::integer,
    (select coalesce(sum(r.total), 0) from results r where r.content_type = t.kind)::integer,
    (select count(*) from results r where r.content_type = t.kind
       and (r.needs_review or r.correct::numeric / r.total < 0.8))::integer,
    (select n from active)
  from unnest(array['food', 'cocktails', 'wine']) as t(kind);
$$;

-- Completed quizzes per week, oldest first, including empty weeks. learner_id null means the whole team.
create or replace function public.activity_by_week(rid uuid, learner_id uuid, weeks integer)
returns table(week_start date, quizzes integer, learners integer)
language sql stable security definer set search_path = '' as $$
  with span as (
    select generate_series(
      date_trunc('week', now()) - make_interval(weeks => greatest(1, least(weeks, 26)) - 1),
      date_trunc('week', now()), interval '1 week')::date as week_start
  ), done as (
    select date_trunc('week', a.created_at)::date as week_start, a.user_id
    from public.quiz_attempts a
    join public.menu_items i on i.id = a.menu_item_id
    where i.restaurant_id = rid and a.total > 0
      and a.created_at >= (select min(s.week_start) from span s)
      and (learner_id is null and exists (select 1 from public.restaurant_members m where m.restaurant_id = rid and m.user_id = a.user_id)
           or a.user_id = learner_id)
  )
  select s.week_start, count(d.user_id)::integer, count(distinct d.user_id)::integer
  from span s left join done d on d.week_start = s.week_start
  group by s.week_start order by s.week_start;
$$;
revoke all on function public.location_stats(uuid), public.activity_by_week(uuid, uuid, integer) from public, anon, authenticated;

-- Manager dashboard: the people who run the team at this location.
create or replace function public.location_summary(rid uuid)
returns table(content_type text, items integer, learners integer, taken integer,
  correct integer, total integer, needs_review integer, active_7d integer)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.can_manage(rid, 'team') then
    raise exception 'Manager access required' using errcode = '42501';
  end if;
  return query select * from public.location_stats(rid);
end $$;

create or replace function public.location_activity(rid uuid, weeks integer default 8)
returns table(week_start date, quizzes integer, learners integer)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.can_manage(rid, 'team') then
    raise exception 'Manager access required' using errcode = '42501';
  end if;
  return query select * from public.activity_by_week(rid, null, weeks);
end $$;

-- Employee dashboard: only ever the signed-in person's own quizzes.
create or replace function public.my_activity(rid uuid, weeks integer default 8)
returns table(week_start date, quizzes integer, learners integer)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.can_read_restaurant(rid) then
    raise exception 'Not a member of this restaurant' using errcode = '42501';
  end if;
  return query select * from public.activity_by_week(rid, (select auth.uid()), weeks);
end $$;

-- Brand dashboard: one row per location, for the brand's owner only.
create or replace function public.brand_summary(oid uuid)
returns table(restaurant_id uuid, name text, items integer, learners integer, taken integer,
  correct integer, total integer, needs_review integer, active_7d integer, quizzes_28d integer)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not exists (select 1 from public.organizations o where o.id = oid and o.owner_id = (select auth.uid())) then
    raise exception 'Only the owner of the brand can compare its locations.' using errcode = '42501';
  end if;
  return query
  select r.id, r.name,
    sum(s.items)::integer, max(s.learners)::integer, sum(s.taken)::integer,
    sum(s.correct)::integer, sum(s.total)::integer, sum(s.needs_review)::integer, max(s.active_7d)::integer,
    (select coalesce(sum(w.quizzes), 0) from public.activity_by_week(r.id, null, 4) w)::integer
  from public.restaurants r
  cross join lateral public.location_stats(r.id) s
  where r.organization_id = oid
  group by r.id, r.name, r.created_at
  order by r.created_at;
end $$;

revoke all on function public.location_summary(uuid), public.location_activity(uuid, integer),
  public.my_activity(uuid, integer), public.brand_summary(uuid) from public, anon;
grant execute on function public.location_summary(uuid), public.location_activity(uuid, integer),
  public.my_activity(uuid, integer), public.brand_summary(uuid) to authenticated;

commit;


-- ===== 037_demo_copies.sql =====
-- Run once, after 036. The demo kitchen becomes a copy per visitor.
--
-- Before: every demo visitor joined the one demo restaurant as a read-only team member, so the
-- guided tour could only point at things. Now each anonymous visitor gets a private copy of it,
-- as its owner: they can add a dish, post a pre-shift, make an invite link, and nobody else sees
-- it. Copies are marked with demo_expires_at and removed by purge_expired_demos() after 7 days.
--
-- The demo restaurant itself (is_demo, from supabase/demo-seed.sql) becomes the template. Nobody
-- joins it any more; its owner still edits it like any restaurant. join_demo() stays, unused.
-- Nothing is dropped, and no restaurant other than expired demo copies is ever deleted.
begin;

alter table public.restaurants add column if not exists demo_expires_at timestamptz;
create index if not exists restaurants_demo_expiry on public.restaurants (demo_expires_at) where demo_expires_at is not null;

-- Opens (or reopens) the visitor's own copy of the demo kitchen. Anonymous accounts only:
-- a real account never gets a throwaway restaurant in its list.
create or replace function public.start_demo()
returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := (select auth.uid());
  template public.restaurants%rowtype;
  rid uuid;
  item public.menu_items%rowtype;
  copy_id uuid;
begin
  if me is null or not public.is_anonymous() then
    raise exception 'The demo kitchen is for visitors without an account.' using errcode = '42501';
  end if;
  select id into rid from public.restaurants where owner_id = me and demo_expires_at is not null;
  if rid is not null then
    return rid;
  end if;
  select * into template from public.restaurants where is_demo;
  if template.id is null then
    raise exception 'The demo kitchen is not set up.' using errcode = 'P0002';
  end if;

  insert into public.restaurants(owner_id, name, demo_expires_at)
  values (me, template.name, now() + interval '7 days')
  returning id into rid;

  insert into public.menu_sections(restaurant_id, content_type, name, heading, about, item_one, item_many)
  select rid, s.content_type, s.name, s.heading, s.about, s.item_one, s.item_many
  from public.menu_sections s where s.restaurant_id = template.id;

  insert into public.menu_categories(restaurant_id, content_type, name, sort_order, archived)
  select rid, c.content_type, c.name, c.sort_order, c.archived
  from public.menu_categories c where c.restaurant_id = template.id;

  -- Every column a dish has, as in import_menu_items. The template has no photos, and any it
  -- gains later stay the template's: a copy starts without them.
  for item in select * from public.menu_items m where m.restaurant_id = template.id order by m.created_at loop
    copy_id := gen_random_uuid();
    insert into public.menu_items
    select * from jsonb_populate_record(null::public.menu_items, to_jsonb(item) || jsonb_build_object(
      'id', copy_id, 'restaurant_id', rid, 'photo_path', null, 'created_at', now(), 'updated_at', now()));
    insert into public.menu_quiz_edits(menu_item_id, questions)
    select copy_id, q.questions from public.menu_quiz_edits q where q.menu_item_id = item.id;
  end loop;

  insert into public.glossary_terms(restaurant_id, term, say, means, note, also, hidden, created_by)
  select rid, g.term, g.say, g.means, g.note, g.also, g.hidden, me
  from public.glossary_terms g where g.restaurant_id = template.id and not g.hidden;

  insert into public.sops(restaurant_id, name, section, why, steps, sort_order, created_by)
  select rid, s.name, s.section, s.why, s.steps, s.sort_order, me
  from public.sops s where s.restaurant_id = template.id;

  return rid;
end $$;
revoke all on function public.start_demo() from public, anon;
grant execute on function public.start_demo() to authenticated;

-- Housekeeping, run on a schedule (see supabase/schedule-demo-cleanup.sql), never from the app.
-- Removes demo copies past their date (their menu, quizzes and members go with them), then the
-- anonymous accounts that no longer own anything. Returns how many copies were removed.
create or replace function public.purge_expired_demos()
returns integer
language plpgsql security definer set search_path = '' as $$
declare removed integer;
begin
  delete from public.restaurants where demo_expires_at is not null and demo_expires_at < now();
  get diagnostics removed = row_count;
  delete from auth.users u
  where u.is_anonymous and u.created_at < now() - interval '8 days'
    and not exists (select 1 from public.restaurants r where r.owner_id = u.id);
  return removed;
end $$;
revoke all on function public.purge_expired_demos() from public, anon, authenticated;

commit;

